import{_ as d,o as e,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const u=JSON.parse('{"title":"低通滤波器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/modules/low_pass/index.md","filePath":"v0.2.0-alpha/modules/low_pass/index.md"}'),c={name:"v0.2.0-alpha/modules/low_pass/index.md"};function r(n,t,l,i,h,s){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="低通滤波器" tabindex="-1">低通滤波器 <a class="header-anchor" href="#低通滤波器" aria-label="Permalink to &quot;低通滤波器&quot;">​</a></h1><p>适用：v0.2.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>low_pass</code> · 模块定义版本：4</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>保留低频成分并衰减较高频率。通过有限长度 FIR 抽头实现，适合去除高频干扰、研究频率选择性，以及为降采样前的带宽限制做准备。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>混合信号.out → 低通滤波器.in → 观察器</code>。同时观察混合信号和滤波结果，先保持相同采样率，再研究抽取或插值。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（输入）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>输入采样率必须等于上游实际速率，它决定 Hz 与数字频率的对应关系。截止频率附近存在过渡带，不能期待在一条频率线上瞬间从全通过变成全阻断。过渡带越窄，通常需要更长抽头和更多计算。</p><p>设计窗影响过渡带与旁瓣取舍；通带增益影响通过部分的大小。抽取与插值不能同时大于 1，输出率按输入率乘插值倍数、再除抽取倍数计算。插值设计使用提高后的设计采样率。</p><p><code>window_param</code> 随设计窗解释：Kaiser 使用 β（≥ 0）；Exponential 使用半窗长度上的衰减 d（dB，≥ 0）；Gaussian 使用 σ（&gt; 0）；Tukey 使用 α（0 ≤ α ≤ 1）。这个参数只对相应四种窗有意义，其他窗不靠它改变。切换窗后按新的含义检查数值，尤其不能给 Tukey 沿用超出 0 到 1 的旧值。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>输入采样率 (Hz)<br><code>sample_rate_hz</code></td><td><code>4096</code></td><td>范围 5e-324 至 1000000；须等于上游实际采样率，可低于 1 Hz。插值滤波按输出采样率设计抽头。</td><td>重新准备</td></tr><tr><td>截止频率 (Hz)<br><code>cutoff_hz</code></td><td><code>256</code></td><td>范围 0 至 500000；须小于设计采样率的一半；插值时设计采样率为输入率乘插值倍数。</td><td>可在线应用</td></tr><tr><td>过渡带宽 (Hz)<br><code>transition_hz</code></td><td><code>128</code></td><td>范围 0 至 500000；须小于设计采样率的一半；插值时设计采样率为输入率乘插值倍数。</td><td>可在线应用</td></tr><tr><td>通带增益<br><code>gain</code></td><td><code>1</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>设计窗函数<br><code>window</code></td><td><code>hamming</code></td><td>Hamming (<code>hamming</code>)；Hann (<code>hann</code>)；Blackman (<code>blackman</code>)；Rectangular (<code>rectangular</code>)；Kaiser (<code>kaiser</code>)；Blackman-Harris (<code>blackman_harris</code>)；Bartlett (<code>bartlett</code>)；Flat top (<code>flattop</code>)；Nuttall (<code>nuttall</code>)；Nuttall CFD (<code>nuttall_cfd</code>)；Welch (<code>welch</code>)；Parzen (<code>parzen</code>)；Exponential (<code>exponential</code>)；Riemann (<code>riemann</code>)；Gaussian (<code>gaussian</code>)；Tukey (<code>tukey</code>)</td><td>可在线应用</td></tr><tr><td>窗参数<br><code>window_param</code></td><td><code>6.76</code></td><td>范围 0 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>抽取倍数<br><code>decimation</code></td><td><code>1</code></td><td>范围 1 至 1024；当前产品支持 1–1024，抽取和插值中最多一个大于 1；修改后须重新准备。</td><td>重新准备</td></tr><tr><td>插值倍数<br><code>interpolation</code></td><td><code>1</code></td><td>范围 1 至 1024；当前产品支持 1–1024，抽取和插值中最多一个大于 1；修改后须重新准备。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>gain</code>、<code>transition_hz</code>、<code>window</code>、<code>window_param</code>、<code>cutoff_hz</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>设计参数按组在线应用，关联字段共同确定新抽头。若新设计超过当前滤波历史容量，按提示重新准备。改变速率关系后也须重新准备；比较时避开启动与改参附近的过渡段。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="实数信号、分支运算与三种选频滤波" tabindex="-1">实数信号、分支运算与三种选频滤波 <a class="header-anchor" href="#实数信号、分支运算与三种选频滤波" aria-label="Permalink to &quot;实数信号、分支运算与三种选频滤波&quot;">​</a></h3><p><a href="../../../downloads/v0.2.0-alpha/real-processing.cnsproj" download>下载 real-processing.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>实数信号、分支运算与三种选频滤波</p><ul><li>64 Hz 与 768 Hz 混合信号分支进入低通、高通、带通；比较增益、相乘、8 点延时与两抽头 FIR。</li></ul><p>实数处理示例将 64 Hz、768 Hz 与噪声的混合信号送入低通。观察输出中 64 Hz 分量保留、768 Hz 分量衰减，并比较相同频率刻度下的幅度。实验来源为本机信号生成。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>截止频率正确却没有滤掉高频？</strong> 先核对填写的输入采样率与上游是否一致，再检查观察器是否绑定滤波器输出。</p><p><strong>抽取后出现新低频？</strong> 检查抽取前是否充分限制带宽，混叠不能靠显示缩放消除。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/06-filter/">06 滤波保留了什么</a></li></ul>',31)])])}const m=d(c,[["render",r]]);export{u as __pageData,m as default};
